From 7e4da0c4e1cdff32eac4274d8f9cc3f425393a8a Mon Sep 17 00:00:00 2001
From: Peder Bergan <contact@pederbe.dev>
Date: Fri, 6 Nov 2026 17:07:42 +0100
Subject: [PATCH] applet: Restore volume slider synchronization after wheel
 changes

Wheel and keyboard step changes assign value, removing its binding to the
device volume. Only a mouse release reinstalls it, leaving subsequent
external volume changes invisible in the popup.

Use an explicit Binding that keeps monitoring volume after assignments and
is disabled while dragging. Reapply it on release without restoring the
old value when the drag begins.

BUG: 527034
---
 applet/ListItemBase.qml | 15 +++++++--------
 1 file changed, 7 insertions(+), 8 deletions(-)

diff --git a/applet/ListItemBase.qml b/applet/ListItemBase.qml
index 83fab21f..ff45d03f 100644
--- a/applet/ListItemBase.qml
+++ b/applet/ListItemBase.qml
@@ -257,11 +257,16 @@ PC3.ItemDelegate {
                     Accessible.name: i18nc("Accessibility data on volume slider", "Adjust volume for %1", item.label)
                     Accessible.onPressAction: moved()

-                    value: to, item.model.Volume
+                    // Keep monitoring the device after wheel and keyboard changes assign value.
+                    Binding on value {
+                        value: slider.to, item.model.Volume
+                        when: !slider.pressed
+                        restoreMode: Binding.RestoreNone
+                    }
                     function increase() { changeVolumeBy(myStepSize) }
                     function decrease() { changeVolumeBy(-myStepSize) }
                     function changeVolumeBy(delta: real) {
-                        value = value + delta;
+                        value = Math.round(value + delta);
                         moved();
                         if (item.type === "sink") {
                             playFeedback(item.model.Index);
@@ -276,12 +281,6 @@ PC3.ItemDelegate {
                     }
                     onPressedChanged: {
                         if (!pressed) {
-                            // Make sure to sync the volume once the button was
-                            // released.
-                            // Otherwise it might be that the slider is at v10
-                            // whereas PA rejected the volume change and is
-                            // still at v15 (e.g.).
-                            value = Qt.binding(() => item.model.Volume);
                             if (type === "sink") {
                                 playFeedback(item.model.Index);
                             }
